"""Writes render/fsr1_source.cpp: AMD's FSR 1 headers (ffx_a.h, ffx_fsr1.h, MIT, see LICENSE.txt here) as
C++ strings, for the shaders the renderer compiles at run time (upscale.cpp). Run it again when the headers
change:  py render/third_party/fsr1/embed_fsr1.py"""
import io, os

here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, "..", "..", "fsr1_source.cpp")


def literal(text):
    # adjacent raw strings of at most 12000 characters each (one string in the end)
    pieces = [text[i:i + 12000] for i in range(0, len(text), 12000)]
    return "\n".join('R"ffx(' + p + ')ffx"' for p in pieces)


parts = []
for name, symbol in (("ffx_a.h", "kFfxA"), ("ffx_fsr1.h", "kFfxFsr1")):
    text = io.open(os.path.join(here, name), encoding="ascii", newline="").read()
    parts.append("extern const char %s[] =\n%s;\n" % (symbol, literal(text)))

io.open(out, "w", encoding="ascii", newline="\n").write(
    "// Generated by render/third_party/fsr1/embed_fsr1.py from AMD's FidelityFX Super Resolution 1 headers\n"
    "// (Copyright (c) 2021 Advanced Micro Devices, Inc.; MIT license: render/third_party/fsr1/LICENSE.txt).\n"
    "// Do not edit; run the script again.\n"
    "namespace render {\n\n" + "\n".join(parts) + "\n}  // namespace render\n")
print("wrote", os.path.normpath(out))
